-- =====================================================================================
-- ABSL Financial - LIVE SCHEMA REPAIR  (foreign keys, CHECK constraints, two enum values)
--
-- Run AFTER LIVE_SERVER_UPDATE.sql. Generated by `php artisan db:schema-diff --print-sql` from a copy of the
-- live data; all 94 statements were applied to that copy with 0 failures (live data satisfies every
-- constraint as of the dump you uploaded). Take a fresh backup first anyway: if rows were added since the
-- dump that break a constraint, that statement is skipped and reported, nothing else is affected.
--
-- WHAT IT FIXES
--   * 57 foreign keys the live database never got (pawning, fixed assets, FD commissions, cash, approvals ...)
--   * 35 CHECK constraints (journal line is one-sided, amounts positive, FD lien, savings amounts ...)
--   * credit_facilities.rate_period lacks 'daily' (Speed Drafts with a daily rate cannot be saved on live)
--   * cashbook_entries.source_type lacks 'FdRenewal' (an FD renewal paying interest in cash fails on live)
--
-- HOW IT RUNS: each statement is tried separately; an error is recorded and the next one still runs.
-- The LAST result grid lists every statement that did not apply (0 rows = everything applied).
-- Running the file again is safe: statements whose constraint already exists are reported as 'already present'.
-- =====================================================================================
DROP PROCEDURE IF EXISTS absl_try;
DROP TABLE IF EXISTS absl_repair_log;
CREATE TABLE absl_repair_log (id INT AUTO_INCREMENT PRIMARY KEY, outcome VARCHAR(20), errno INT NULL, message VARCHAR(300), statement_text VARCHAR(400)) ENGINE=InnoDB;
DELIMITER $$
CREATE PROCEDURE absl_try(IN stmt TEXT)
BEGIN
  DECLARE v_errno INT DEFAULT 0;
  DECLARE v_msg VARCHAR(300) DEFAULT '';
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 v_errno = MYSQL_ERRNO, v_msg = MESSAGE_TEXT;
  END;
  SET @absl_stmt = stmt;
  PREPARE st FROM @absl_stmt;
  IF v_errno = 0 THEN
    EXECUTE st;
    DEALLOCATE PREPARE st;
  END IF;
  IF v_errno = 0 THEN
    INSERT INTO absl_repair_log (outcome, errno, message, statement_text) VALUES ('applied', NULL, '', LEFT(stmt, 400));
  ELSEIF v_errno IN (1826, 1061, 1060, 4025, 1022) OR v_msg LIKE '%Duplicate%' OR v_msg LIKE '%already exists%' THEN
    INSERT INTO absl_repair_log (outcome, errno, message, statement_text) VALUES ('already present', v_errno, LEFT(v_msg, 300), LEFT(stmt, 400));
  ELSE
    INSERT INTO absl_repair_log (outcome, errno, message, statement_text) VALUES ('FAILED', v_errno, LEFT(v_msg, 300), LEFT(stmt, 400));
  END IF;
END$$
DELIMITER ;

