-- ------------------------------------------------------------------ RESULT (one grid)
SELECT outcome, COUNT(*) AS statements FROM absl_repair_log GROUP BY outcome
UNION ALL SELECT CONCAT('FAILED #', id, ' (errno ', errno, ')'), 0 FROM absl_repair_log WHERE outcome = 'FAILED'
UNION ALL SELECT CONCAT('   ', message, ' <= ', statement_text), 0 FROM absl_repair_log WHERE outcome = 'FAILED';

DROP PROCEDURE absl_try;
-- DROP TABLE absl_repair_log;   -- keep it until you have read the result above; drop it afterwards
